class Rows:
    def __init__(self, rows):
        self.rows = list(rows)
        self.index = 0
        self.reads = 0
        self.closes = 0

    def read_next(self):
        self.reads += 1
        if self.index == len(self.rows):
            return None
        value = self.rows[self.index]
        self.index += 1
        return value

    def close(self):
        self.closes += 1

